export const language=playable.some(l=>l.code===requested)?requested:DEFAULT_LANGUAGE;
// Page texts: the language's own dictionary, then English, then Brazilian Portuguese.
const ui=dictionaries[languageInfo(language).ui]||dictionaries.en;
export function t(key,values={}){let value=ui[key]??dictionaries.en[key]??dictionaries['pt-BR'][key]??key;for(const [name,text]of Object.entries(values))value=value.replaceAll(`{${name}}`,text);return value;}
export function applyLocale(){
 document.documentElement.lang=language;
 const picker=document.querySelector('#language');picker.replaceChildren(...playable.map(l=>{const option=document.createElement('option');option.value=l.code;option.textContent=l.name;return option;}));picker.value=language;
 for(const item of document.querySelectorAll('[data-i18n]'))item.textContent=t(item.dataset.i18n);
 for(const item of document.querySelectorAll('[data-i18n-placeholder]'))item.placeholder=t(item.dataset.i18nPlaceholder);
 const byId={play:'play','open-settings':'settings',inventory:'inventory','save-game':'save','load-saved':'loadShort',journal:'journal',fullscreen:'fullscreen',continue:'continue','launch-detail':'launch','save-state':'progress'};
 for(const[id,key]of Object.entries(byId))document.getElementById(id).textContent=t(key);
 document.querySelector('.scope').textContent=t('scope');document.querySelector('.welcome .eyebrow').textContent=t('welcome');document.querySelector('.intro').textContent=t('journey');document.querySelector('.edition span').textContent=t('edition');document.querySelector('.game-help>span').textContent=t(matchMedia('(pointer:coarse)').matches?'touchHelp':'help');
 document.querySelector('.reading-sample p').textContent=t('sample');
 for(const item of document.querySelectorAll('.close'))item.setAttribute('aria-label',t('close'));
 document.querySelector('#save-slots').setAttribute('aria-label',t('savedGames'));document.querySelector('#language').setAttribute('aria-label',t('language'));
 document.querySelector('#settings .eyebrow').textContent=t('readingEyebrow');document.querySelector('#settings h2').textContent=t('readingTitle');
 document.querySelector('label[for=font-family]').textContent=t('readingStyle');
 const sizeLabel=document.querySelector('label[for=font-size]');sizeLabel.firstChild.textContent=t('fontSize')+' ';
 document.querySelector('label[for=contrast]').textContent=t('contrastLabel');
 for(const key of ['literary','clear','classic'])document.querySelector(`[data-font=${key}]`).textContent=t(key);
 document.querySelector('#contrast option[value=soft]').textContent=t('soft');document.querySelector('#contrast option[value=high]').textContent=t('high');
 document.querySelector('#settings .fine-print').textContent=t('fontNote');document.querySelector('#export-save').textContent=t('exportSave');document.querySelector('#import-save').textContent=t('importSave');document.querySelector('#new-game').textContent=t('newGame');
 document.querySelector('#journal-panel .eyebrow').textContent=t('memories');document.querySelector('#journal-panel h2').textContent=t('journal');document.querySelector('#journal-panel .empty').textContent=t('emptyJournal');
}
